import 'package:flutter/material.dart'; import '../../../core/network/football_repository.dart';
class TransfersScreen extends StatelessWidget{const TransfersScreen({super.key});@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Transfer Center')),body:FutureBuilder<List<dynamic>>(future:FootballRepository().transfers(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return RefreshIndicator(onRefresh:()async{},child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:s.data!.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(_,i){final x=s.data![i];return Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.swap_horiz)),title:Text(x['player']?['name']??'Player'),subtitle:Text('${x['from_team']?['name']??'—'}  →  ${x['to_team']?['name']??'—'}'),trailing:Text(x['type']??'')));}));}));}}
